CREATE EXTENSION IF NOT EXISTS pgcrypto;

CREATE TABLE usuario (
    id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    usuario VARCHAR(100) NOT NULL UNIQUE,
    senha VARCHAR(100) NOT NULL,
    ativo BOOLEAN NOT NULL DEFAULT TRUE,
    criado_em TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    notificar_conta_vencendo_whatsapp BOOLEAN NOT NULL DEFAULT FALSE,
    notificar_conta_vencendo_ntfy BOOLEAN NOT NULL DEFAULT FALSE,
    topico_ntfy VARCHAR(80)
);
CREATE TABLE papeis (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,nome VARCHAR(100) NOT NULL UNIQUE,descricao VARCHAR(255),ativo BOOLEAN NOT NULL DEFAULT TRUE,criado_em TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP);
ALTER TABLE usuario ADD COLUMN papel_id BIGINT REFERENCES papeis(id);
CREATE TABLE papel_funcionalidades (papel_id BIGINT NOT NULL REFERENCES papeis(id) ON DELETE CASCADE,funcionalidade VARCHAR(60) NOT NULL,PRIMARY KEY(papel_id,funcionalidade));
CREATE TABLE contatos_whatsapp_usuario (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,usuario_id BIGINT NOT NULL REFERENCES usuario(id) ON DELETE CASCADE,numero VARCHAR(16) NOT NULL,UNIQUE(usuario_id,numero));
CREATE TABLE contas (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,descricao VARCHAR(255) NOT NULL,valor_total NUMERIC(15,2) NOT NULL CHECK(valor_total>0),qtd_parcelas INTEGER NOT NULL DEFAULT 1 CHECK(qtd_parcelas>0),usuario_cadastro BIGINT REFERENCES usuario(id),tipo VARCHAR(7) NOT NULL CHECK(tipo IN('RECEBER','PAGAR')),situacao VARCHAR(9) NOT NULL DEFAULT 'ABERTA' CHECK(situacao IN('ABERTA','PAGA','RECEBIDA','PARCELADA')),criado_em TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,baixada_em TIMESTAMP WITH TIME ZONE);
CREATE TABLE parcelas_contas (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,conta_id BIGINT NOT NULL REFERENCES contas(id) ON DELETE CASCADE,numero INTEGER NOT NULL CHECK(numero>0),valor NUMERIC(15,2) NOT NULL CHECK(valor>0),data_vencimento DATE NOT NULL,situacao VARCHAR(9) NOT NULL DEFAULT 'PENDENTE' CHECK(situacao IN('PENDENTE','PAGA','RECEBIDA')),baixada_em TIMESTAMP WITH TIME ZONE,observacao_baixa VARCHAR(1000),UNIQUE(conta_id,numero));
CREATE TABLE anexos_contas (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,conta_id BIGINT NOT NULL REFERENCES contas(id) ON DELETE CASCADE,nome_arquivo VARCHAR(255) NOT NULL,descricao VARCHAR(255) NOT NULL,tipo_arquivo VARCHAR(150),tamanho BIGINT NOT NULL,conteudo BYTEA NOT NULL,criado_em TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP);
INSERT INTO usuario(usuario,senha) VALUES('admin',crypt('admin',gen_salt('bf',12))) ON CONFLICT(usuario) DO NOTHING;
